#!/usr/bin/env node
// Run every scenarios/<name>/ through the BUILT headless CLI (same command the grader uses),
// twice for determinism, check expect.json, and save evidence.
//
//   node scripts/proof.mjs --phase phase-1     -> writes docs/proof/phase-1/
//   node scripts/proof.mjs --check             -> check only, writes to out/proof (CI)
//
// Exit 1 if any scenario fails. Never edit the generated files by hand.
import { execFileSync, spawnSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";

const root = resolve(import.meta.dirname, "..");
const argv = process.argv.slice(2);
const phase = argv.includes("--phase") ? argv[argv.indexOf("--phase") + 1] : null;
const check = argv.includes("--check") || !phase;
const outDir = check ? join(root, "out", "proof") : join(root, "docs", "proof", phase);
mkdirSync(outDir, { recursive: true });

const contract = JSON.parse(readFileSync(join(root, "game.contract.json"), "utf8"));
const [cmd, ...cmdArgs] = contract.headless_cmd.split(" ");
const cli = join(root, "dist", "headless", "cli.js");
if (!existsSync(cli)) {
  console.error("dist/headless/cli.js missing - run `npm run build` first");
  process.exit(1);
}

function runOnce(dir, exp, out) {
  const args = [...cmdArgs, "--seed", String(exp.seed ?? 1), "--night", "1", "--ticks", String(exp.ticks), "--out", out];
  if (existsSync(join(dir, "scenario.json"))) args.push("--scenario", join(dir, "scenario.json"));
  if (existsSync(join(dir, "inputs.json"))) args.push("--inputs", join(dir, "inputs.json"));
  if (exp.snapshot_every) args.push("--snapshot-every", String(exp.snapshot_every));
  const r = spawnSync(cmd, args, { cwd: root, encoding: "utf8" });
  return { code: r.status, stderr: r.stderr.trim(), cmdline: `${cmd} ${args.map((a) => a.replace(root + "\\", "").replace(root + "/", "")).join(" ")}` };
}

const near = (a, b) => Math.abs(a - b) <= 1e-3;
const rows = [];
let failed = 0;

for (const name of readdirSync(join(root, "scenarios")).sort()) {
  const dir = join(root, "scenarios", name);
  if (!existsSync(join(dir, "expect.json"))) continue;
  const exp = JSON.parse(readFileSync(join(dir, "expect.json"), "utf8"));
  const e = exp.expect ?? {};
  const outA = join(outDir, `${name}.jsonl`);
  const outB = join(root, "out", `${name}.rerun.jsonl`);
  mkdirSync(join(root, "out"), { recursive: true });
  const a = runOnce(dir, exp, outA);
  const problems = [];

  if (e.exit_code !== undefined) {
    if (a.code !== e.exit_code) problems.push(`exit ${a.code} != ${e.exit_code}`);
  } else if (a.code !== 0) {
    problems.push(`exit ${a.code}: ${a.stderr}`);
  } else {
    const b = runOnce(dir, exp, outB);
    if (readFileSync(outA, "utf8") !== readFileSync(outB, "utf8")) problems.push("NOT deterministic (2 runs differ)");
    const lines = readFileSync(outA, "utf8").trim().split("\n").map((l) => JSON.parse(l));
    const end = lines.at(-1);
    if (end.type !== "end") problems.push("last line is not end");
    if (e.end_state && end.state !== e.end_state) problems.push(`end.state ${end.state} != ${e.end_state}`);
    if (e.end_ticks !== undefined && end.ticks !== e.end_ticks) problems.push(`end.ticks ${end.ticks} != ${e.end_ticks}`);
    if (e.end_score !== undefined && end.score !== e.end_score) problems.push(`end.score ${end.score} != ${e.end_score}`);
    const names = lines.filter((l) => l.type === "event").map((l) => l.name);
    for (const ev of e.events ?? []) if (!names.includes(ev)) problems.push(`missing event ${ev}`);
    for (const ev of e.absent_events ?? []) if (names.includes(ev)) problems.push(`unexpected event ${ev}`);
    if (e.player_pos_at_end) {
      const snap = lines.filter((l) => l.type === "snapshot").at(-1);
      if (!snap.player.pos.every((v, i) => near(v, e.player_pos_at_end[i])))
        problems.push(`player.pos ${JSON.stringify(snap.player.pos)} != ${JSON.stringify(e.player_pos_at_end)}`);
    }
  }
  if (problems.length) failed++;
  rows.push({ name, desc: exp.description ?? "", cmd: a.cmdline, ok: problems.length === 0, problems });
  console.log(`${problems.length ? "FAIL" : "PASS"}  ${name}${problems.length ? "  - " + problems.join("; ") : ""}`);
}

let commit = "unknown";
try {
  commit = execFileSync("git", ["rev-parse", "--short", "HEAD"], { cwd: root, encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).trim();
} catch {}
const md = [
  `# Proof run ${phase ?? "check"}`,
  "",
  `Generated by \`node scripts/proof.mjs${phase ? " --phase " + phase : ""}\` at commit \`${commit}\` (${new Date().toISOString()}). Do not edit by hand.`,
  `Node ${process.version}, ${process.platform}/${process.arch}.`,
  "",
  "| Scenario | What it proves | Command | Result |",
  "|---|---|---|---|",
  ...rows.map((r) => `| ${r.name} | ${r.desc} | \`${r.cmd}\` | ${r.ok ? "PASS (deterministic)" : "FAIL: " + r.problems.join("; ")} |`),
  "",
  `Total: ${rows.length - failed}/${rows.length} pass.`,
  "",
].join("\n");
writeFileSync(join(outDir, "RESULTS.md"), md);
console.log(`\n${rows.length - failed}/${rows.length} pass -> ${outDir}`);
process.exit(failed ? 1 : 0);
